import{bQ as a,aL as i,u as t,G as n}from"./chunks/framework.D06dwy5q.js";const c=JSON.parse('{"title":"08｜主从复制","description":"","frontmatter":{},"headers":[],"relativePath":"05.Redis/08-主从复制.md","filePath":"05.Redis/08-主从复制.md","lastUpdated":null}'),e={name:"05.Redis/08-主从复制.md"};function p(l,s,h,d,k,r){return i(),t("div",null,[...s[0]||(s[0]=[n(`<h1 id="_08-主从复制" tabindex="-1">08｜主从复制 <a class="header-anchor" href="#_08-主从复制" aria-label="Permalink to &quot;08｜主从复制&quot;">​</a></h1><p>单机 Redis 跑了一段时间，数据已经有一些了。现在加一台机器做从库，把主库的数据同步过去——读请求可以分担，主库宕机时从库有完整副本可以接管。</p><p>从库连上主库后，主库的变更会自动同步过来。但复制不是强一致的——主库写入成功返回后，从库可能还没来得及收到。主库突然故障时，最后一段数据可能丢失。复制提供的是&quot;副本&quot;和&quot;恢复基础&quot;，不是数据库级别的强一致。</p><p>主从复制也是 Sentinel 和 Cluster 的基础——后面两篇的高可用方案都建立在复制之上。</p><h2 id="一、建立复制" tabindex="-1">一、建立复制 <a class="header-anchor" href="#一、建立复制" aria-label="Permalink to &quot;一、建立复制&quot;">​</a></h2><p>主库已经在 <code>192.168.10.11:6379</code> 上运行。从库装好 Redis 后，只需一行配置让它连上主库：</p><div class="language-conf vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">conf</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># 从库 /etc/redis/redis.conf</span></span>
<span class="line"><span>bind 127.0.0.1 192.168.10.129</span></span>
<span class="line"><span>port 6379</span></span>
<span class="line"><span>replicaof 192.168.10.11 6379</span></span>
<span class="line"><span>appendonly yes</span></span></code></pre></div><p><code>replicaof</code> 告诉从库：启动后去连 <code>192.168.10.11:6379</code>，同步数据。如果主库有密码，从库还要配 <code>masterauth</code>：</p><div class="language-conf vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">conf</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>masterauth strong_password_here</span></span></code></pre></div><p>重启从库：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> restart</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> redis</span></span></code></pre></div><p>从库连上主库后，第一件事是确认链路状态：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">redis-cli</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -h</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 192.168.10.129</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> INFO</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> replication</span></span></code></pre></div><p>输出里能看到几个关键信息：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>role:slave</span></span>
<span class="line"><span>master_host:192.168.10.11</span></span>
<span class="line"><span>master_port:6379</span></span>
<span class="line"><span>master_link_status:up</span></span>
<span class="line"><span>master_repl_offset:1234567</span></span>
<span class="line"><span>slave_repl_offset:1234567</span></span></code></pre></div><p><code>role:slave</code> 表示当前角色是从库；<code>master_link_status:up</code> 表示跟主库的链路正常；两个 offset 相等，说明从库已经追上了主库，没有延迟。</p><p>主库上写一条，从库上立刻查：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 主库</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">redis-cli</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -h</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 192.168.10.11</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> SET</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test:replica</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;hello&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 从库</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">redis-cli</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -h</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 192.168.10.129</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> GET</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test:replica</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># &quot;hello&quot;</span></span></code></pre></div><p>同步在工作。从库默认只读——直接写入会报错：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">redis-cli</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -h</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 192.168.10.129</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> SET</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> x</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># (error) READONLY You can&#39;t write against a read only replica.</span></span></code></pre></div><p>这个限制能防止应用误写从库。故障切换时新主库会自动取消这个限制。</p><h2 id="二、复制状态怎么看" tabindex="-1">二、复制状态怎么看 <a class="header-anchor" href="#二、复制状态怎么看" aria-label="Permalink to &quot;二、复制状态怎么看&quot;">​</a></h2><p><code>INFO replication</code> 是排查复制问题的核心入口。主库上的输出：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">redis-cli</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -h</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 192.168.10.11</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> INFO</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> replication</span></span></code></pre></div><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>role:master</span></span>
<span class="line"><span>connected_slaves:2</span></span>
<span class="line"><span>master_repl_offset:2345678</span></span>
<span class="line"><span>repl_backlog_active:1</span></span>
<span class="line"><span>repl_backlog_size:1048576</span></span></code></pre></div><p><code>connected_slaves</code> 是当前连接的从库数量；<code>master_repl_offset</code> 是主库每写入一条命令就增长的&quot;复制偏移量&quot;，可以把它理解成&quot;主库总共写了多少字节的数据流&quot;；<code>repl_backlog_active</code> 是主库是否在维护一个&quot;复制积压缓冲区&quot;——这个缓冲区保存了最近一段写命令，从库短暂断开后重连时，如果断开期间的数据还在缓冲区里，就只补增量，不用再做全量同步。</p><p>判断延迟的核心方法是对比主从的 offset：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 主库上</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">redis-cli</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -h</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 192.168.10.11</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> INFO</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> replication</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> grep</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> master_repl_offset</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 从库上</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">redis-cli</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -h</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 192.168.10.129</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> INFO</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> replication</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> grep</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> slave_repl_offset</span></span></code></pre></div><p>两者的差值就是当前未同步的字节量。差值持续扩大说明从库追不上主库——可能的原因：网络带宽不够、从库 CPU 或磁盘慢、主库写入量太大、从库正在做 BGSAVE 或 AOF 重写抢了资源。</p><h2 id="三、全量复制与部分复制" tabindex="-1">三、全量复制与部分复制 <a class="header-anchor" href="#三、全量复制与部分复制" aria-label="Permalink to &quot;三、全量复制与部分复制&quot;">​</a></h2><p>从库初次连接主库时，主库里已经有一堆数据了——从库不可能知道之前发生了什么，只能拿一份完整快照重新开始。这个过程叫<strong>全量复制</strong>：</p><div class="mermaid-diagram" data-mermaid-code="flowchart%20LR%0A%20%20%20%20replica%5B%22%E4%BB%8E%E5%BA%93%E8%BF%9E%E6%8E%A5%E4%B8%BB%E5%BA%93%22%5D%20--%3E%20fork%5B%22%E4%B8%BB%E5%BA%93%20fork%5Cn%E7%94%9F%E6%88%90%20RDB%22%5D%0A%20%20%20%20fork%20--%3E%20send%5B%22%E5%8F%91%E9%80%81%20RDB%5Cn%E5%88%B0%E4%BB%8E%E5%BA%93%22%5D%0A%20%20%20%20send%20--%3E%20load%5B%22%E4%BB%8E%E5%BA%93%E5%8A%A0%E8%BD%BD%20RDB%22%5D%0A%20%20%20%20load%20--%3E%20incr%5B%22%E7%BB%A7%E7%BB%AD%E6%8E%A5%E6%94%B6%20RDB%20%E4%B9%8B%E5%90%8E%5Cn%E4%BA%A7%E7%94%9F%E7%9A%84%E5%A2%9E%E9%87%8F%E5%91%BD%E4%BB%A4%22%5D%0A"></div><p>主库 fork 子进程生成 RDB 快照，通过网络发给从库，从库加载这份快照后，再接收快照生成之后的新写入。全量复制期间主库的 fork 和 RDB 传输都会消耗资源——如果从库很多且同时发起全量复制（比如所有从库同时重启），主库的压力是叠加的。重启从库要错开时间。</p><p>但从库如果只是短暂断网几秒钟，没必要再做一次全量复制——断开期间的那几条写入完全可以补发过去。主库维护了一个<strong>复制积压缓冲区</strong>（backlog），是一个环形缓冲区，记录最近的写命令：</p><div class="language-conf vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">conf</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>repl-backlog-size 256mb</span></span>
<span class="line"><span>repl-backlog-ttl 3600</span></span></code></pre></div><p>从库重连后上报自己的 offset，主库检查这个 offset 是否还在 backlog 的范围内——在的话只发缺失的那段增量，这叫<strong>部分复制</strong>；不在的话就只能走全量复制。</p><p><code>repl-backlog-size</code> 设多少合适？按&quot;写入速率 × 期望容忍的最大断开时间&quot;估算。如果主库每秒写入 10MB，期望 60 秒内的断链都能走部分复制，backlog 至少需要 10MB × 60 = 600MB。设太小频繁全量复制，设太大浪费内存。</p><p><code>repl-backlog-ttl</code> 是当所有从库都断开、且超过这个时间（秒）后，主库释放 backlog 以节省内存。</p><p>全量复制时还可以选择不走磁盘：</p><div class="language-conf vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">conf</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>repl-diskless-sync yes</span></span></code></pre></div><p>默认情况下，主库先把 RDB 写到磁盘文件，再发给从库——磁盘慢时这个&quot;先写盘&quot;步骤是瓶颈。<code>repl-diskless-sync yes</code> 让 RDB 直接通过 socket 发送，不额外落盘。代价是 RDB 数据缓存在主库内存中再通过 socket 发送，如果 RDB 很大（比如几十 GB），主库内存压力会短暂升高。</p><h2 id="四、运行时动态管理复制" tabindex="-1">四、运行时动态管理复制 <a class="header-anchor" href="#四、运行时动态管理复制" aria-label="Permalink to &quot;四、运行时动态管理复制&quot;">​</a></h2><p>复制关系也可以在运行时建立或取消，不用改配置文件重启：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 让当前实例成为从库</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">redis-cli</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> REPLICAOF</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 192.168.10.11</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 6379</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 让从库脱离复制，变成独立主库</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">redis-cli</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> REPLICAOF</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> NO</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ONE</span></span></code></pre></div><p>运行时命令适合临时操作，但持久化配置要写进配置文件——不然重启后会恢复到配置文件里定义的拓扑。</p><p><code>REPLICAOF NO ONE</code> 是手工切换的核心步骤。Sentinel 自动故障转移时，本质上就是选一台从库执行这个命令，把它提升为新主库，再通知其他从库改挂新主。</p><h2 id="五、读写分离" tabindex="-1">五、读写分离 <a class="header-anchor" href="#五、读写分离" aria-label="Permalink to &quot;五、读写分离&quot;">​</a></h2><p>读写分离的典型路径：写请求进主库，读请求走从库，主库把变更异步推给从库。</p><div class="mermaid-diagram" data-mermaid-code="flowchart%20LR%0A%20%20%20%20app%5B%22%E5%BA%94%E7%94%A8%22%5D%20--%3E%20write%5B%22%E5%86%99%E8%AF%B7%E6%B1%82%22%5D%0A%20%20%20%20app%20--%3E%20read%5B%22%E8%AF%BB%E8%AF%B7%E6%B1%82%22%5D%0A%20%20%20%20write%20--%3E%20master%5B%22Redis%20%E4%B8%BB%E5%BA%93%22%5D%0A%20%20%20%20master%20--%3E%20repl%5B%22%E5%BC%82%E6%AD%A5%E5%A4%8D%E5%88%B6%E6%B5%81%22%5D%0A%20%20%20%20repl%20--%3E%20replica%5B%22Redis%20%E4%BB%8E%E5%BA%93%22%5D%0A%20%20%20%20read%20--%3E%20replica%0A"></div><p>核心问题是复制延迟——刚写到主库的数据，去从库读可能还没到。处理方式分场景：</p><table tabindex="0"><thead><tr><th>场景</th><th>适合读从库</th><th>不适合</th></tr></thead><tbody><tr><td>首页配置、排行榜、统计</td><td>延迟几秒不影响展示</td><td>—</td></tr><tr><td>备份导出</td><td>避免主库直接承受备份读取</td><td>—</td></tr><tr><td>大量读请求分摊</td><td>读多写少，能容忍短暂延迟</td><td>—</td></tr><tr><td>刚写完马上要读到</td><td>—</td><td>复制延迟导致读到旧值</td></tr><tr><td>库存扣减、余额判断</td><td>—</td><td>一致性要求高</td></tr><tr><td>分布式锁状态</td><td>—</td><td>延迟会破坏互斥判断</td></tr></tbody></table><p>业务如果要求&quot;读己之写&quot;（刚写入的数据立即能读到），写之后的读请求要发给主库，或者在应用层做短时间的主库读标记。</p><h2 id="六、复制安全参数" tabindex="-1">六、复制安全参数 <a class="header-anchor" href="#六、复制安全参数" aria-label="Permalink to &quot;六、复制安全参数&quot;">​</a></h2><p>主库可以配置：在从库数量不足或延迟过高时拒绝写入，降低&quot;孤岛写入&quot;的风险：</p><div class="language-conf vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">conf</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>min-replicas-to-write 1      # 至少 1 个从库满足条件才允许写</span></span>
<span class="line"><span>min-replicas-max-lag 10      # 从库延迟超过 10 秒就不算&quot;满足条件&quot;</span></span></code></pre></div><p>从库全部异常时，主库会拒绝写入——宁愿短时间写失败，也不让主库在没有副本的情况下持续写入。一旦主库在这期间宕机，数据就永久丢失了。对数据安全性要求高的核心系统会开这个参数；纯缓存场景通常不开，因为这等于让从库的可用性绑架了主库的可用性。</p><p>单次写入后也可以用 <code>WAIT</code> 命令确认副本接收情况：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">redis-cli</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> SET</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> order:1001</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status:paid</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">redis-cli</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> WAIT</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1000</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # 等至少 1 个从库确认收到，最多等 1000ms</span></span></code></pre></div><p><code>WAIT</code> 返回实际确认的从库数量。返回 0 说明超时前没有从库确认——但写入在主库上已经成功了。这不是事务回滚，业务代码要处理&quot;主库写成功但副本未确认&quot;的中间状态。</p><h2 id="七、复制异常排查" tabindex="-1">七、复制异常排查 <a class="header-anchor" href="#七、复制异常排查" aria-label="Permalink to &quot;七、复制异常排查&quot;">​</a></h2><table tabindex="0"><thead><tr><th>现象</th><th>排查方向</th></tr></thead><tbody><tr><td><code>master_link_status:down</code></td><td>网络不通、主库密码错、防火墙拦截、主库 bind 没绑从库能连到的地址</td></tr><tr><td>反复全量复制</td><td>backlog 太小、网络频繁抖动、从库频繁重启</td></tr><tr><td>从库延迟持续扩大</td><td>主库写入量超出从库处理能力、网络带宽瓶颈、从库在做 BGSAVE/AOF rewrite</td></tr><tr><td>从库连不上主库</td><td><code>ss -lntp</code> 确认主库监听地址、安全组/防火墙规则、<code>masterauth</code> 密码、protected-mode</td></tr></tbody></table><p>排查步骤：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 从库侧测试主库端口是否可达</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">nc</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -vz</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 192.168.10.11</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 6379</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 从库侧测试密码是否正确</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">redis-cli</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -h</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 192.168.10.11</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -a</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;strong_password_here&#39;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> PING</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 看主从双方日志</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">journalctl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -u</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> redis-6379</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -n</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 100</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --no-pager</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tail</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -n</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 100</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /var/log/redis/redis-6379.log</span></span></code></pre></div><p>复制异常时把 <code>INFO replication</code> 的完整输出保存下来——它记录了当时的角色、offset、链路状态和从库数量，复盘时不用靠猜。</p><h2 id="八、从库做备份" tabindex="-1">八、从库做备份 <a class="header-anchor" href="#八、从库做备份" aria-label="Permalink to &quot;八、从库做备份&quot;">​</a></h2><p>从库常被用来承担备份任务，避免主库执行 <code>BGSAVE</code> 时的 fork 影响主库性能：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">redis-cli</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -h</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 192.168.10.129</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> BGSAVE</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">redis-cli</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -h</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 192.168.10.129</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> INFO</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> persistence</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> grep</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rdb_last_bgsave_status</span></span></code></pre></div><p>但从库备份的前提是延迟不大——如果从库已经落后很多，备份出来的 RDB 也落后同样多。备份前检查：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">redis-cli</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -h</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 192.168.10.129</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> INFO</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> replication</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> grep</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -E</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;master_link_status|master_last_io_seconds_ago&#39;</span></span></code></pre></div><p><code>master_link_status</code> 为 up 且 <code>master_last_io_seconds_ago</code> 在几秒以内，备份的数据才算&quot;够新&quot;。备份成功和数据够新是两件事。</p><h2 id="九、手工切换" tabindex="-1">九、手工切换 <a class="header-anchor" href="#九、手工切换" aria-label="Permalink to &quot;九、手工切换&quot;">​</a></h2><p>Sentinel 或 Cluster 自动切换之前，手工切换是排查和演练的基础：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 1. 在选定的从库上提升为主库</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">redis-cli</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -h</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 192.168.10.129</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> REPLICAOF</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> NO</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ONE</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 2. 确认新主库角色</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">redis-cli</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -h</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 192.168.10.129</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> INFO</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> replication</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> grep</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> role</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 3. 旧主库恢复后，作为新主库的从库加入，避免双主写入</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">redis-cli</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -h</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 192.168.10.11</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> REPLICAOF</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 192.168.10.129</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 6379</span></span></code></pre></div><p>手工切换最麻烦的不是这几条命令，而是应用连接怎么切到新主库、旧主库残留的写入怎么处理、其他从库要不要改挂新主。切完之后除了 <code>PING</code>，还要做一次写入验证确认新主库确实可写。</p>`,74)])])}const F=a(e,[["render",p]]);export{c as __pageData,F as default};
